            write_persisted_atomic(archive_root / "manifest.json", manifest)
            _write_archive_event(
                archive_root,
                {"schema": ARCHIVE_EVENT_SCHEMA, "archive_id": archive_id, "paper_id": paper_id, "operation_id": operation_id, "state": "archived"},
